import assert from 'node:assert/strict';
export async function exercise(page, context, fail = false) {
  await page.goto('https://example.com', {waitUntil:'domcontentloaded', timeout:30000});
  assert.equal(await page.title(), 'Example Domain');
  await page.evaluate(() => {
    document.body.innerHTML = `<h1>Inventory fixture</h1><label>Quantity<input id="quantity" type="number" value="1"></label><button id="calculate">Calculate</button><output id="total"></output><input id="upload" type="file"><table><tbody><tr><td>Notebook</td><td>7</td></tr><tr><td>Pen</td><td>3</td></tr></tbody></table>`;
    document.querySelector('#calculate').onclick=()=>document.querySelector('#total').textContent=String(Number(document.querySelector('#quantity').value)*7);
  });
  await page.locator('#quantity').fill('4');
  await page.locator('#calculate').click();
  const total=await page.locator('#total').textContent();
  const rows=await page.locator('tr').evaluateAll(rows=>rows.map(r=>Array.from(r.cells,c=>c.textContent)));
  await page.locator('#upload').setInputFiles({name:'inventory.txt',mimeType:'text/plain',buffer:Buffer.from('migration fixture')});
  const upload=await page.locator('#upload').evaluate(async e=>e.files[0].text());
  const screenshot=await page.screenshot({type:'png'});
  assert.equal(total,'28');assert.deepEqual(rows,[['Notebook','7'],['Pen','3']]);assert.equal(upload,'migration fixture');
  assert.equal(screenshot.subarray(0,8).toString('hex'),'89504e470d0a1a0a');
  await context.addCookies([{name:'fixture',value:'retained',domain:'example.com',path:'/',secure:true,sameSite:'Lax'}]);
  await page.evaluate(()=>localStorage.setItem('fixture','retained'));
  if(fail)throw new Error('intentional-workflow-failure');
  return {total,rows,upload,screenshot:true};
}

