import Kernel from '@onkernel/sdk';
const client=new Kernel({apiKey:process.env.KERNEL_API_KEY});
async function start(){const s=await client.browsers.create({headless:true});return {id:s.session_id,url:s.cdp_ws_url};}
async function stop(id){await client.browsers.deleteByID(id);}
import {chromium} from 'playwright-core';
import assert from 'node:assert/strict';
import {exercise} from './workflow.mjs';
export async function run({fail=false}={}) {
 const session=await start();let browser;let primary;
 try {
  browser=await chromium.connectOverCDP(session.url,{timeout:30000});
  const context=browser.contexts()[0];const page=context.pages()[0]??await context.newPage();
  const result=await exercise(page,context,fail);
  await browser.close();browser=null;
  browser=await chromium.connectOverCDP(session.url,{timeout:30000});
  const restored=browser.contexts()[0];const next=restored.pages()[0];
  assert.equal(await next.evaluate(()=>localStorage.getItem('fixture')),'retained');
  assert.ok((await restored.cookies('https://example.com')).some(c=>c.name==='fixture'&&c.value==='retained'));
  return {...result,reconnect:true};
 }catch(e){primary=e;throw e;}
 finally{let cleanup;try{await browser?.close();}catch(e){cleanup=e;}try{await stop(session.id);}catch(e){cleanup??=e;}if(!primary&&cleanup)throw cleanup;}
}

