import Steel from 'steel-sdk';
import puppeteer from 'puppeteer-core';
import assert from 'node:assert/strict';
export async function run({fail=false}={}) {
 const client=new Steel({steelAPIKey:process.env.STEEL_API_KEY});
 const session=await client.sessions.create({timeout:120000});let browser;let primary;
 try {
  const url=new URL('wss://connect.steel.dev');url.searchParams.set('apiKey',process.env.STEEL_API_KEY);url.searchParams.set('sessionId',session.id);
  browser=await puppeteer.connect({browserWSEndpoint:String(url),protocolTimeout:30000});
  const page=(await browser.pages())[0]??await browser.newPage();
  await page.goto('https://example.com',{waitUntil:'domcontentloaded',timeout:30000});
  await page.evaluate(()=>{document.body.innerHTML='<h1>Report fixture</h1><input id="name"><button id="save">Save</button><output id="result"></output>';document.querySelector('#save').onclick=()=>{document.querySelector('#result').textContent='Hello '+document.querySelector('#name').value;localStorage.setItem('report',document.querySelector('#name').value);};});
  await page.type('#name','Ada');await page.click('#save');
  const greeting=await page.$eval('#result',e=>e.textContent);assert.equal(greeting,'Hello Ada');
  const screenshot=await page.screenshot({type:'png'});assert.equal(Buffer.from(screenshot).subarray(0,8).toString('hex'),'89504e470d0a1a0a');
  if(fail)throw new Error('intentional-workflow-failure');
  await browser.disconnect();browser=null;
  browser=await puppeteer.connect({browserWSEndpoint:String(url),protocolTimeout:30000});
  const next=(await browser.pages())[0];const stored=await next.evaluate(()=>localStorage.getItem('report'));assert.equal(stored,'Ada');
  return {greeting,screenshot:true,stored,reconnect:true};
 }catch(e){primary=e;throw e;}
 finally{let cleanup;try{await browser?.disconnect();}catch(e){cleanup=e;}try{await client.sessions.release(session.id);}catch(e){cleanup??=e;}if(!primary&&cleanup)throw cleanup;}
}

