import {Stagehand} from '@browserbasehq/stagehand';
import assert from 'node:assert/strict';
import {z} from 'zod';
export async function run(){
 const stagehand=new Stagehand({env:'BROWSERBASE',apiKey:process.env.BROWSERBASE_API_KEY,projectId:process.env.BROWSERBASE_PROJECT_ID,browserbaseSessionCreateParams:{timeout:120},verbose:0,disablePino:true,logger:()=>{}});
 try {
  await stagehand.init();
  const page=stagehand.context.pages()[0];await page.goto('https://example.com');
  const title=await page.title();assert.equal(title,'Example Domain');
  await page.evaluate(()=>{document.body.innerHTML='<h1>Order fixture</h1><input id="quantity" value="1"><button id="calculate">Calculate</button><output id="total"></output>';document.querySelector('#calculate').onclick=()=>document.querySelector('#total').textContent=String(Number(document.querySelector('#quantity').value)*7);});
  await stagehand.act('Fill the quantity input with 4');
  await stagehand.act('Click the Calculate button');
  const {total}=await stagehand.extract('Extract the calculated total shown in the output element',z.object({total:z.string()}));assert.equal(total,'28');
  return {title,total};
 }finally{await stagehand.close();}
}
